{"command":"mkdir -p /tmp/work && cat > /workspace/main.c <<'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <math.h>
#include <stdint.h>
#include <zlib.h>
#include <unistd.h>

// ---------- utilities ----------
static void *xmalloc(size_t n){ void *p=malloc(n?n:1); if(!p){exit(1);} return p; }
static void *xrealloc(void *q,size_t n){ void *p=realloc(q,n?n:1); if(!p){exit(1);} return p; }
static char *xstrdup(const char *s){ size_t n=strlen(s); char *p=xmalloc(n+1); memcpy(p,s,n+1); return p; }

typedef struct { char *s; size_t l,m; } dstr_t;
static void ds_init(dstr_t *d){ d->m=16; d->l=0; d->s=xmalloc(d->m); d->s[0]=0; }
static void ds_free(dstr_t *d){ free(d->s); d->s=NULL; d->l=d->m=0; }
static void ds_clear(dstr_t *d){ d->l=0; if(d->s) d->s[0]=0; }
static void ds_ensure(dstr_t *d,size_t need){ if(need>d->m){ size_t nm=d->m?d->m:16; while(nm<need) nm*=2; d->s=xrealloc(d->s,nm); d->m=nm; } }
static void ds_append_n(dstr_t *d,const char *s,size_t n){ ds_ensure(d,d->l+n+1); memcpy(d->s+d->l,s,n); d->l+=n; d->s[d->l]=0; }
static void ds_append(dstr_t *d,const char *s){ ds_append_n(d,s,strlen(s)); }
static void ds_append_c(dstr_t *d,char c){ ds_ensure(d,d->l+2); d->s[d->l++]=c; d->s[d->l]=0; }
static void ds_set_n(dstr_t *d,const char *s,size_t n){ ds_clear(d); ds_append_n(d,s,n); }
static void ds_set(dstr_t *d,const char *s){ ds_set_n(d,s,strlen(s)); }

// ---------- RNG (placeholder, to be refined) ----------
static uint64_t rng_state=11;
static uint64_t rng_splitmix_next(void){
    uint64_t z=(rng_state+=0x9e3779b97f4a7c15ULL);
    z=(z^(z>>30))*0xbf58476d1ce4e5b9ULL;
    z=(z^(z>>27))*0x94d049bb133111ebULL;
    return z^(z>>31);
}
static void rng_seed(uint64_t s){ rng_state=s; }
static double rng_double(void){ return (double)(rng_splitmix_next()>>11)*(1.0/9007199254740992.0); }
static uint64_t rng_uint64(void){ return rng_splitmix_next(); }

// ---------- sequence record & reader ----------
typedef struct { dstr_t name, comment, seq, qual; } rec_t;
static void rec_init(rec_t *r){ ds_init(&r->name); ds_init(&r->comment); ds_init(&r->seq); ds_init(&r->qual); }
static void rec_free(rec_t *r){ ds_free(&r->name); ds_free(&r->comment); ds_free(&r->seq); ds_free(&r->qual); }
static void rec_clear(rec_t *r){ ds_clear(&r->name); ds_clear(&r->comment); ds_clear(&r->seq); ds_clear(&r->qual); }
static void rec_copy(rec_t *dst, const rec_t *src){
    ds_set_n(&dst->name, src->name.s, src->name.l);
    ds_set_n(&dst->comment, src->comment.s, src->comment.l);
    ds_set_n(&dst->seq, src->seq.s, src->seq.l);
    ds_set_n(&dst->qual, src->qual.s, src->qual.l);
}

typedef struct { gzFile fp; char *pending; } reader_t;

// read a line, strip trailing \n and \r\n. Return malloc'd string or NULL at EOF with no data.
static char *reader_getline(reader_t *rd){
    size_t cap=256, len=0; char *buf=xmalloc(cap);
    int c;
    // Use gzgets in chunks
    while(1){
        if(cap-len < 64){ cap*=2; buf=xrealloc(buf,cap); }
        char *res=gzgets(rd->fp, buf+len, (int)(cap-len));
        if(!res){ break; }
        size_t got=strlen(buf+len);
        len+=got;
        if(len>0 && buf[len-1]=='\n') break;
        if(got==0) break;
        // if buffer filled exactly without newline, loop to extend
        if(cap-len>1) break; // EOF partial?
        // Actually gzgets stops at newline or EOF or len-1; if no newline and not EOF continue
        if(gzeof(rd->fp)) break;
    }
    if(len==0 && gzeof(rd->fp)){ free(buf); return NULL; }
    if(len==0){ // could be empty? check feof
        // gzgets returned NULL
        free(buf); return NULL;
    }
    // strip \n then \r
    while(len>0 && (buf[len-1]=='\n' || buf[len-1]=='\r')){ // careful: only strip one \n and optional \r? for our use strip trailing \r\n sequence; but sequence may end with \r intentionally? assume strip \n then \r
        break;
    }
    if(len>0 && buf[len-1]=='\n'){ buf[--len]=0; if(len>0 && buf[len-1]=='\r') buf[--len]=0; }
    // Note: lines cut by CRLF handled. Lone \r at EOF left as is? original removes? ignore
    return buf;
}

static void reader_init_file(reader_t *rd, gzFile fp){ rd->fp=fp; rd->pending=NULL; }
static void reader_close(reader_t *rd){ if(rd->fp) gzclose(rd->fp); free(rd->pending); }

// return >=0 seq len, -1 EOF, -2 malformed (qual mismatch)
static int reader_next(reader_t *rd, rec_t *rec){
    rec_clear(rec);
    char *hdr=NULL;
    if(rd->pending){ hdr=rd->pending; rd->pending=NULL; }
    else {
        while(1){
            char *line=reader_getline(rd);
            if(!line) return -1;
            if(line[0]=='>' || line[0]=='@'){ hdr=line; break; }
            free(line);
        }
    }
    // parse header
    {
        char *p=hdr+1;
        char *start=p;
        while(*p && !isspace((unsigned char)*p)) p++;
        ds_set_n(&rec->name, start, (size_t)(p-start));
        if(*p){
            // comment is after single delimiter char
            ds_set(&rec->comment, p+1);
        } else {
            ds_clear(&rec->comment);
        }
    }
    free(hdr);
    // seq phase
    while(1){
        char *line=reader_getline(rd);
        if(!line){ return (int)rec->seq.l; }
        if(line[0]=='>' || line[0]=='@'){ rd->pending=line; return (int)rec->seq.l; }
        if(line[0]=='+'){ free(line); goto qual_phase; }
        ds_append(&rec->seq, line);
        free(line);
