        case 'B': return 'V'; case 'D': return 'H'; case 'H': return 'D'; case 'V': return 'B';
        case 'K': return 'M'; case 'M': return 'K'; case 'R': return 'Y'; case 'Y': return 'R';
        case 'a': return 't'; case 'c': return 'g'; case 'g': return 'c'; case 't': case 'u': return 'a';
        case 'b': return 'v'; case 'd': return 'h'; case 'h': return 'd'; case 'v': return 'b';
