// ---------- size ----------
static int cmd_size(int argc, char *argv[]){
    gzFile fp;
    if(argc>1) fp=open_input_file(argv[1]); else fp=gzdopen(fileno(stdin),"rb");
    if(!fp){ fprintf(stderr,"[E::stk_size] failed to open the input file/stream.\n"); return 1; }
    reader_t rd; reader_init_file(&rd,fp); rec_t rec; rec_init(&rec);
    long long n=0,total=0; int l; while((l=reader_next(&rd,&rec))>=0){ n++; total+=rec.seq.l; }
    printf("%lld\t%lld\n",n,total);
    rec_free(&rec); reader_close(&rd); return 0;
}
// ---------- comp ----------
static int cmd_comp(int argc, char *argv[]){
    int upper_only=0; int c; long rarg=0; (void)rarg;
    // getopt string r:u as discovered
    while((c=getopt(argc,argv,"r:u"))!=-1){ switch(c){ case 'u': upper_only=1; break; case 'r': rarg=strtol(optarg,NULL,10); break; default: break; } }
    gzFile fp; if(optind<argc) fp=open_input_file(argv[optind]); else fp=gzdopen(fileno(stdin),"rb");
    if(!fp){ fprintf(stderr,"[E::stk_comp] failed to open the input file/stream.\n"); return 1; }
    reader_t rd; reader_init_file(&rd,fp); rec_t rec; rec_init(&rec); int l;
    // Need understand -r: maybe no effect in most cases; store for later
    while((l=reader_next(&rd,&rec))>=0){
        long long cnt[8]={0}; // A C G T amb2 amb3 other + ?
        long long cpg=0, ts=0, tv=0, cpg_amb=0; // columns 9-12: cpg, tv?, ts?, amb cpg?
        // We'll compute per sequence
        // Classification per base:
        for(size_t i=0;i<rec.seq.l;i++){
            unsigned char ch=(unsigned char)rec.seq.s[i];
            int is_lower = (ch>='a' && ch<='z');
            if(upper_only && is_lower){
                // counts skipped, but CpG handling below separately using ??? Observations: lower bases still contribute 1 to cpg count per pair side? We'll handle in cpg loop separately
                // For classification, skip
            } else {
                int up=toupper(ch);
                if(up=='A') cnt[0]++;
                else if(up=='C') cnt[1]++;
                else if(up=='G') cnt[2]++;
                else if(up=='T') cnt[3]++;
                else if(up=='R'||up=='Y'||up=='S'||up=='W'||up=='K'||up=='M'){
                    cnt[4]++;
                    if(up=='R'||up=='Y') ts++; else tv++;
                }
                else if(up=='B'||up=='D'||up=='H'||up=='V') cnt[5]++;
                else cnt[6]++;
            }
        }
        // CpG: for each adjacent pair (i,i+1) where first in {C,Y} (case-insensitive?) and second in {G,R}
        // count 2 per such pair? But with -u, lower contributes 1 per side. Model: count per position:
        // For each i, if seq[i] is C/c/Y/y (?) and i+1 exists and next is G/R, then increment cpg if base counted (not lower when -u?...)
        // Similarly, if seq[i] is G/R and previous is C/Y, increment.
        // That yields 2 per pair normally, 1 when one side lower & -u.
        // Ambiguous CpG count cpg_amb: per pair as above, count number of ambiguous bases among the two (Y/R) ... If pair (C,G) 0, (C,R)1, (Y,G)1, (Y,R)2.
        // But -u effect on cpg_amb also: yR with -u gave 1: ambiguous count also per counted side? pair y(lower not counted) + R upper => 1. CG pair -u etc 0.
        for(size_t i=0;i+1<rec.seq.l;i++){
            unsigned char a=(unsigned char)rec.seq.s[i], b=(unsigned char)rec.seq.s[i+1];
            int au=toupper(a), bu=toupper(b);
            if((au=='C'||au=='Y') && (bu=='G'||bu=='R')){
                // left contribution
                if(!(upper_only && a>='a' && a<='z')) { cpg++; if(au=='Y') cpg_amb++; }
                if(!(upper_only && b>='a' && b<='z')) { cpg++; if(bu=='R') cpg_amb++; }
            }
