                // In old1/old2 case, old2 is pending at EOF (first of its group) so stale. In a/1,a/2 case, a/2 is second of group, printed directly (?) no stale.
                // Implement: only if k==0 (group leader) and index>0 and no comment, use latest previous comment.
                if(k==0 && (i+k)>0){
                    const char *stale=NULL; size_t stale_l=0;
                    for(long j=(long)(i+k)-1;j>=0;j--){ if(items[j].r.comment.l){ stale=items[j].r.comment.s; stale_l=items[j].r.comment.l; break; } }
                    if(stale){ fputc(' ',stdout); fwrite(stale,1,stale_l,stdout); }
                }
            }
            fputc('\n',stdout);
            print_wrapped(stdout,r->seq.s,r->seq.l,0);
            if(!is_fa){ fputs("+\n",stdout); print_wrapped(stdout,r->qual.s,r->qual.l,0); }
        }
        i+=group;
    }
    for(size_t i=0;i<n;i++) rec_free(&items[i].r); free(items);
    rec_free(&rec); reader_close(&rd); return 0;
}
// ---------- hpc ----------
static int cmd_hpc(int argc, char *argv[]){
    gzFile fp; if(argc>1) fp=open_input_file(argv[1]); else fp=gzdopen(fileno(stdin),"rb");
    if(!fp){ fprintf(stderr,"[E::stk_hpc] failed to open the input file/stream.\n"); return 1; }
    reader_t rd; reader_init_file(&rd,fp); rec_t rec; rec_init(&rec); int l;
    while((l=reader_next(&rd,&rec))>=0){
        if(rec.seq.l==0) continue; // observed empty dropped
        // compress runs of same char
        dstr_t out; ds_init(&out);
        for(size_t i=0;i<rec.seq.l;i++){ if(i==0 || rec.seq.s[i]!=rec.seq.s[i-1]) ds_append_c(&out,rec.seq.s[i]); }
        fputc('>',stdout); fwrite(rec.name.s,1,rec.name.l,stdout); fputc('\n',stdout);
        // original hpc drops comment (observed)
        print_wrapped(stdout,out.s,out.l,0);
        ds_free(&out);
    }
    rec_free(&rec); reader_close(&rd); return 0;
}
