// ---------- fqchk ----------
typedef struct { long long cnt; long long base[5]; double sum_q; double sum_e; long long low, high; long long *qcnt; } fqpos_t;
static void fqpos_init(fqpos_t *p){ memset(p,0,sizeof(*p)); p->qcnt=xmalloc(sizeof(long long)*256); memset(p->qcnt,0,sizeof(long long)*256); }
static int cmd_fqchk(int argc, char *argv[]){
    int qth=20; int c;
    while((c=getopt(argc,argv,"q:"))!=-1){ switch(c){ case 'q': qth=atoi(optarg); break; default: break; } }
    if(optind>=argc){ fprintf(stderr,"Usage: seqtk fqchk [-q %d] <in.fq>\nNote: use -q0 to get the distribution of all quality values\n",qth); return 1; }
    gzFile fp=open_input_file(argv[optind]);
    if(!fp){ fprintf(stderr,"[E::stk_fqchk] failed to open the input file/stream.\n"); return 1; }
    reader_t rd; reader_init_file(&rd,fp); rec_t rec; rec_init(&rec);
    fqpos_t *pos=NULL; size_t npos=0, mpos=0; // index 0 = ALL, 1.. = positions (1-based)
    // Ensure at least ALL
    mpos=16; pos=xmalloc(sizeof(fqpos_t)*mpos); for(size_t i=0;i<mpos;i++) fqpos_init(&pos[i]); npos=1;
    long long min_len=9223372036854775807LL, max_len=0, total_len=0, nrec=0;
    int distinct_q[256]={0}; // by unsigned char? qval+?? We'll map by char value (0-255)
    int l;
    while((l=reader_next(&rd,&rec))>=0){
        if(rec.qual.l==0) continue;
        nrec++; total_len+=rec.seq.l; if((long long)rec.seq.l<min_len) min_len=(long long)rec.seq.l; if((long long)rec.seq.l>max_len) max_len=(long long)rec.seq.l;
        // ensure pos up to seq.l (pos index = i+1)
        if(rec.seq.l+1>npos){
            size_t needed=rec.seq.l+1;
            if(needed>mpos){ size_t old=mpos; while(mpos<needed) mpos*=2; pos=xrealloc(pos,sizeof(fqpos_t)*mpos); for(size_t i=old;i<mpos;i++) fqpos_init(&pos[i]); }
            npos=needed;
        }
        for(size_t i=0;i<rec.seq.l;i++){
            unsigned char base=(unsigned char)rec.seq.s[i]; unsigned char qc=(unsigned char)rec.qual.s[i];
            int qv=(int)qc-33;
            distinct_q[qc]=1;
            // update ALL (0) and position i+1
            for(int rep=0;rep<2;rep++){
                fqpos_t *p=&pos[rep==0?0:i+1];
                p->cnt++;
                int up=toupper(base);
                int bi = (up=='A')?0:(up=='C')?1:(up=='G')?2:(up=='T')?3:4;
                p->base[bi]++;
                p->sum_q += qv;
                double prob=pow(10.0, - ((qv<3?3:qv)/10.0) );
                // cap above? max with q>=3 ensures prob <=0.501
                p->sum_e += prob;
                if(qth!=0){ if(qv < qth) p->low++; else p->high++; }
                else { if(qc<256) p->qcnt[qc]++; }
            }
        }
    }
    // distinct count and sorted list by qv ascending (char ascending gives q ascending)
    int ndist=0; for(int i=0;i<256;i++) if(distinct_q[i]) ndist++;
    printf("min_len: %lld; max_len: %lld; avg_len: %.2f; %d distinct quality values\n", min_len, max_len, nrec? (double)total_len/(double)nrec : 0.0/0.0, ndist);
    // header
    printf("POS\t#bases\t%%A\t%%C\t%%G\t%%T\t%%N\tavgQ\terrQ");
    if(qth==0){ for(int i=0;i<256;i++) if(distinct_q[i]) printf("\t%%Q%d", i-33); }
    else printf("\t%%low\t%%high");
    printf("\n");
    // rows: ALL then 1..max_len
    size_t nrows = (size_t)max_len;
    for(size_t r=0;r<=nrows;r++){
        fqpos_t *p=&pos[r];
        if(r==0) printf("ALL"); else printf("%zu",r);
        printf("\t%lld",p->cnt);
        for(int bi=0;bi<5;bi++) printf("\t%.1f", p->cnt? 100.0*(double)p->base[bi]/(double)p->cnt : 0.0/0.0);
        double avgq = p->cnt? p->sum_q/(double)p->cnt : 0.0/0.0;
        double errq;
        if(p->cnt==0) errq=-0.0; else errq=-10.0*log10((p->sum_e + 1e-6)/(double)p->cnt);
        printf("\t%.1f\t%.1f",avgq,errq);
        if(qth==0){
            for(int i=0;i<256;i++) if(distinct_q[i]) printf("\t%.2f", p->cnt? 100.0*(double)p->qcnt[i]/(double)p->cnt : 0.0/0.0);
        } else {
            printf("\t%.1f\t%.1f", p->cnt?100.0*(double)p->low/(double)p->cnt:0.0/0.0, p->cnt?100.0*(double)p->high/(double)p->cnt:0.0/0.0);
        }
        printf("\n");
    }
    for(size_t i=0;i<mpos;i++) free(pos[i].qcnt); free(pos);
    rec_free(&rec); reader_close(&rd); return 0;
}
'''
