static int cmd_gc(int argc, char *argv[]){
    // Check usage first based on current defaults? Original usage varies with options, and if optind>=argc it prints usage with current values.
    int at_mode=0; double frac=0.60; int min_len=20; double xdrop=10.0; int c;
