    if(optind>=argc){
        fprintf(stderr,"Usage: seqtk gc [options] <in.fa>\nOptions:\n  -w         identify high-AT regions\n  -f FLOAT   min GC fraction (or AT fraction for -w) [%.2f]\n  -l INT     min region length to output [%d]\n  -x FLOAT   X-dropoff [%.1f]\n",frac,min_len,xdrop);
        return 1;
    }
