    if(!fp){ fprintf(stderr,"[E::stk_gc] failed to open the input file/stream.\n"); return 1; }
    reader_t rd; reader_init_file(&rd,fp); rec_t rec; rec_init(&rec); int l;
    double a = frac==0? 0 : (1.0-frac)/frac; // if frac==0, a=inf in original? We'll set large?
