    while((l=reader_next(&rd,&rec))>=0){
        long start=0; double score=0, max_score=0; long max_pos=0;
        // helper inline via macro-like code: output when segment qualifies
        for(size_t i=0;i<rec.seq.l;i++){
            int up=toupper((unsigned char)rec.seq.s[i]);
            int is_target = at_mode ? (up=='A'||up=='T'||up=='W') : (up=='G'||up=='C'||up=='S');
