                    long cnt=0; for(long j=start;j<max_pos;j++){ int u2=toupper((unsigned char)rec.seq.s[j]); int tg= at_mode?(u2=='A'||u2=='T'||u2=='W'):(u2=='G'||u2=='C'||u2=='S'); if(tg) cnt++; }
