            printf("%s\t%ld\t%ld\t%ld\n",rec.name.s,start,max_pos,cnt);
        }
    }
    rec_free(&rec); reader_close(&rd); return 0;
}
// ---------- cutN ----------
static int cmd_cutN(int argc, char *argv[]){
    int min_n=1000, penalty=10, gaps_only=0; int c;
    while((c=getopt(argc,argv,"n:p:g"))!=-1){ switch(c){ case 'n': min_n=atoi(optarg); break; case 'p': penalty=atoi(optarg); break; case 'g': gaps_only=1; break; default: break; } }
    if(optind>=argc){
        fprintf(stderr,"\nUsage:   seqtk cutN [options] <in.fa>\n\nOptions: -n INT    min size of N tract [%d]\n         -p INT    penalty for a non-N [%d]\n         -g        print gaps only, no sequence\n\n",min_n,penalty);
        return 1;
    }
    gzFile fp=open_input_file(argv[optind]);
    if(!fp){ fprintf(stderr,"[E::stk_cutN] failed to open the input file/stream.\n"); return 1; }
    reader_t rd; reader_init_file(&rd,fp); rec_t rec; rec_init(&rec); int l;
    while((l=reader_next(&rd,&rec))>=0){
        // find gaps
        typedef struct { long beg,end; } gap_t;
        gap_t *gaps=NULL; size_t ng=0, mg=0;
        long start=0; double score=0, peak=0; long peak_pos=0;
        for(size_t i=0;i<rec.seq.l;i++){
            int isN = (rec.seq.s[i]=='N' || rec.seq.s[i]=='n');
