static scanres_t telo_scan(const char *seq, long len, const char *motif_u, int L, const char **rots, int nrots, int penalty, int dropoff){
    scanres_t res; res.S=xmalloc(sizeof(long)*(len+1)); res.S[0]=0; res.maxscore=0; res.maxpos=0; res.stop=len;
    long score=0;
    // Build rotation check via string compare each time (len may be large but okay)
    for(long pos=0; pos<len; pos++){
        long next_pos=pos+1; long delta=0;
        if(next_pos > L && L>0){
