static scanres_t telo_scan(const char *seq, long len, int L, const char **rots, int nrots, int penalty, int dropoff, int start_w){
    scanres_t res; res.B=xmalloc(sizeof(long)*(len+1)); for(long i=0;i<=len;i++) res.B[i]=0; res.maxscore=0; res.maxpos=0; res.break_coord=len+1; res.truncated=0;
