#include <stdio.h>
#include <stdint.h>
#include <string.h>
#define NN 312
#define MM 156
static uint64_t mt[NN]; static int idx_;
static void init_mt(uint64_t seed){ mt[0]=seed; for(int i=1;i<NN;i++) mt[i]=6364136223846793005ULL*(mt[i-1]^(mt[i-1]>>62))+i; idx_=NN; }
static uint64_t gen_mt(void){
 const uint64_t UM=0xFFFFFFFF80000000ULL, LM=0x7FFFFFFFULL, MA=0xB5026F5AA96619E9ULL;
 if(idx_>=NN){
   for(int i=0;i<NN-MM;i++){ uint64_t x=(mt[i]&UM)|(mt[i+1]&LM); uint64_t xA=x>>1; if(x&1) xA^=MA; mt[i]=mt[i+MM]^xA; }
   for(int i=NN-MM;i<NN-1;i++){ uint64_t x=(mt[i]&UM)|(mt[i+1]&LM); uint64_t xA=x>>1; if(x&1) xA^=MA; mt[i]=mt[i+(MM-NN)]^xA; }
   { uint64_t x=(mt[NN-1]&UM)|(mt[0]&LM); uint64_t xA=x>>1; if(x&1) xA^=MA; mt[NN-1]=mt[MM-1]^xA; }
   idx_=0;
 }
 uint64_t y=mt[idx_++];
 y ^= (y>>29) & 0x5555555555555555ULL; y ^= (y<<17) & 0x71D67FFFEDA60000ULL; y ^= (y<<37) & 0xFFF7EEE000000000ULL; y ^= y>>43; return y;
}
static const char *target="11111111011000010111000001001001001111000101001101010101001000101111001000000011110000101111011101100010111000101010001000100111110010010100100000101111111111111010011011001010101111000010000101001100";
int main(){
 int N=200000;
 uint64_t seeds[4]={11ULL,0ULL,1ULL,5489ULL};
 for(int mode=0; mode<3; mode++){
  for(int si=0;si<4;si++){
   uint64_t seed=seeds[si];
   init_mt(seed);
   static unsigned char bits[200005];
   for(int i=0;i<N;i++){ uint64_t v=gen_mt(); int b = mode==0 ? (int)((v>>63)&1) : mode==1 ? (int)(v&1) : (int)((v>>32)&1); bits[i]=(unsigned char)b; }
   for(int off=0; off<N-200; off++){ int ok=1; for(int i=0;i<200;i++) if(bits[off+i]!=target[i]-'0'){ ok=0; break; } if(ok) printf("MATCH mode %d seed %llu offset %d\n",mode,(unsigned long long)seed,off); }
  }
 }
 printf("done\n"); return 0;
}
EOF
