import subprocess, os, random, math
os.chdir("/tmp/t")
E="/workspace/executable"
def orig_err(quals):
    # quals list of q ints at a single position: construct reads of length1
    with open("qf.fq","w") as f:
        for q in quals: f.write(f"@r\nA\n+\n{chr(q+33)}\n")
    r=subprocess.run([E,"fqchk","qf.fq"],capture_output=True,text=True)
    for line in r.stdout.splitlines():
        if line.startswith("ALL"):
            return float(line.split("\t")[8])
def candidates(quals):
    n=len(quals)
    out={}
    def err_from_sum(s): return -10*math.log10(s/n) if s>0 else 999
    out['our_clamp3_plus1e-6']=-10*math.log10((sum(10**(-max(q,3)/10) for q in quals)+1e-6)/n)
    out['cap05_plus1e-6']=-10*math.log10((sum(min(0.5,10**(-q/10)) for q in quals)+1e-6)/n)
    out['clamp3_noeps']=err_from_sum(sum(10**(-max(q,3)/10) for q in quals))
    out['noclamp']=-10*math.log10((sum(10**(-q/10) for q in quals)+1e-6)/n)
    out['solexa']=-10*math.log10((sum(1/(1+10**(q/10)) for q in quals)+1e-6)/n)
    # prob using natural exp approximation q * 0.2302585 vs log
    out['exp_approx']=-10*math.log10((sum(math.exp(-q*0.23) if q>=3 else math.exp(-3*0.23) for q in quals)+1e-6)/n)
    return out
random.seed(2)
scores={}
examples=[]
for trial in range(100):
    quals=[random.randint(0,50) for _ in range(random.randint(2,10))]
    o=orig_err(quals)
    cand=candidates(quals)
    for k,v in cand.items():
        # printed rounding: v should round to o with %.1f (C rounding)
        pred=float(f"{v:.1f}")
        if pred!=o:
            scores[k]=scores.get(k,0)+1
            if k=='our_clamp3_plus1e-6' and len(examples)<10: examples.append((quals,o,v))
print("mismatch counts out of 100:",scores)
for e in examples: print(e)
