def pcg32_stream(initstate,initseq,n=200):
    state=0; inc=((initseq<<1)|1) & ((1<<64)-1)
    def nxt():
        nonlocal state
        old=state
        state=(old*6364136223846793005+inc) & ((1<<64)-1)
        xorshifted=(((old>>18)^old)>>27) & 0xffffffff
        rot=old>>59
        return ((xorshifted>>rot) | (xorshifted<<((-rot)&31))) & 0xffffffff
    nxt(); state=(state+initstate) & ((1<<64)-1); nxt()
    return [nxt() for _ in range(n)]

