            int up=toupper(ch);
            if(up=='A') cnt[0]++; else if(up=='C') cnt[1]++; else if(up=='G') cnt[2]++; else if(up=='T') cnt[3]++;
            else if(up=='R'||up=='Y'||up=='S'||up=='W'||up=='K'||up=='M'){ cnt[4]++; if(up=='R'||up=='Y') ts++; else tv++; }
            else if(up=='B'||up=='D'||up=='H'||up=='V') cnt[5]++; else cnt[6]++;
        }
    }
    for(size_t i=0;i+1<seq_len;i++){
        unsigned char a=(unsigned char)seqstr[i], b=(unsigned char)seqstr[i+1]; int au=toupper(a), bu=toupper(b);
        if((au=='C'||au=='Y') && (bu=='G'||bu=='R')){
            if(!(upper_only && a>='a' && a<='z')) { cpg++; if(au=='Y') cpg_amb++; }
            if(!(upper_only && b>='a' && b<='z')) { cpg++; if(bu=='R') cpg_amb++; }
        }
    }
    if(region_mode) printf("%s\t%ld\t%ld\t%lld\t%lld\t%lld\t%lld\t%lld\t%lld\t%lld\t%lld\t%lld\t%lld\t%lld\n",name,field2,field3,cnt[0],cnt[1],cnt[2],cnt[3],cnt[4],cnt[5],cnt[6],cpg,tv,ts,cpg_amb);
    else printf("%s\t%zu\t%lld\t%lld\t%lld\t%lld\t%lld\t%lld\t%lld\t%lld\t%lld\t%lld\t%lld\n",name,seq_len,cnt[0],cnt[1],cnt[2],cnt[3],cnt[4],cnt[5],cnt[6],cpg,tv,ts,cpg_amb);
    (void)out;
}
static int cmd_comp(int argc, char *argv[]){
    int upper_only=0; int c; const char *region_file=NULL;
    while((c=getopt(argc,argv,"r:u"))!=-1){ switch(c){ case 'u': upper_only=1; break; case 'r': region_file=optarg; break; default: break; } }
    regions_t regs={0}; int region_mode=0;
    if(region_file){ if(read_regions(region_file,&regs,0)==0) region_mode=1; else { regs.n=0; region_mode=0; } }
    gzFile fp; if(optind<argc) fp=open_input_file(argv[optind]); else fp=gzdopen(fileno(stdin),"rb");
    if(!fp){ fprintf(stderr,"[E::stk_comp] failed to open the input file/stream.\n"); regions_free(&regs); return 1; }
    reader_t rd; reader_init_file(&rd,fp); rec_t rec; rec_init(&rec); int l;
    while((l=reader_next(&rd,&rec))>=0){
        if(region_mode){
            for(size_t ri=0;ri<regs.n;ri++){
                region_t *rg=&regs.a[ri];
                if(!rg->is_region) continue;
                if(strcmp(rg->name,rec.name.s)!=0) continue;
                long beg=rg->beg; long end=rg->end;
                long cbeg=beg<0?0:(beg>(long)rec.seq.l?(long)rec.seq.l:beg);
                long cend=end<0?0:(end>(long)rec.seq.l?(long)rec.seq.l:end);
                if(cend<cbeg) cend=cbeg;
                // Build subsequence string (null-terminated subarray)
                dstr_t sub; ds_init(&sub); if(cend>cbeg) ds_append_n(&sub, rec.seq.s+cbeg, (size_t)(cend-cbeg));
                comp_print_counts(stdout, rec.name.s, beg, end, 1, sub.s, sub.l, upper_only);
                ds_free(&sub);
            }
        } else {
            comp_print_counts(stdout, rec.name.s, 0,0,0, rec.seq.s, rec.seq.l, upper_only);
        }
    }
    rec_free(&rec); reader_close(&rd); regions_free(&regs); return 0;
}
