import subprocess, os, random, sys, shutil, gzip
ORIG="/workspace/executable"; MY="/tmp/myexe"; BASE="/tmp/fuzzwork"
def run_one(exe,args,data,cwd,extra):
    for n,c in extra.items():
        with open(os.path.join(cwd,n),'wb') as f: f.write(c if isinstance(c,bytes) else c.encode())
    if isinstance(data,str): data=data.encode()
    r=subprocess.run([exe]+args,input=data,capture_output=True,cwd=cwd)
    files={}
    for n in sorted(os.listdir(cwd)):
        if n in extra: continue
        files[n]=open(os.path.join(cwd,n),'rb').read()
    return r.stdout,r.stderr,r.returncode,files
def compare(args,data=None,files=None,label=""):
    files=files or {}; res=[]
    for tag,exe in [("orig",ORIG),("my",MY)]:
        cwd=os.path.join(BASE,tag); shutil.rmtree(cwd,ignore_errors=True); os.makedirs(cwd)
        res.append(run_one(exe,args,data,cwd,files))
    ok=res[0]==res[1]
    if not ok:
        print("DIFF",label,args)
        a,b=res
        if a[0]!=b[0]: print(" out orig",a[0][:600],"\n my",b[0][:600])
        if a[1]!=b[1]: print(" err orig",a[1][:500],"\n my",b[1][:500])
        if a[2]!=b[2]: print(" rc",a[2],b[2])
        if a[3]!=b[3]: print(" files differ",list(a[3]),list(b[3]))
    return ok
random.seed(4); total=ok=0
def T(*a,**k):
    global total,ok; total+=1
    if compare(*a,**k): ok+=1

